// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address[] memory tos, uint256 v) public {
        vm.assume(from != address(0));
        vm.assume(tos.length > 0 && tos.length <= 8);
        for (uint256 i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0));
        }
        // Low-level calls to plain (EOA) addresses succeed, so the loop completes
        // and the reference contract must return true for every admissible input.
        vm.prank(from);
        bool ok = c.transfer(from, from, tos, v);
        assertTrue(ok, "successful batch transfer must return true");
    }
}
